cd /tmp/claude-uid/*/*/scratchpad/rerun/evals/terraform-secure-iac/results/raw/2026-10-28/tsi-04-ci-apply-role/with-skill/run-2/workspace && cat > ci_access.tf <<'EOF'
# AWS side of the CI handover: GitHub OIDC federation and the roles the
# platform/ingest workflow assumes. No static keys are created.

variable "github_repository" {
  description = "GitHub repository (owner/name) whose workflow may assume the CI roles. Changing it changes which repository the role trust policies accept."
  type        = string
  default     = "platform/ingest"
}

variable "github_apply_ref" {
  description = "Git ref whose workflow runs may assume the apply role. Changing it changes which branch can run terraform apply."
  type        = string
  default     = "refs/heads/main"
}

data "aws_caller_identity" "current" {}

locals {
  state_bucket_arn = "arn:aws:s3:::ingest-terraform-state"
  state_key_arn    = "${local.state_bucket_arn}/ingest/terraform.tfstate"
  state_lock_arn   = "${local.state_key_arn}.tflock"

  managed_arns = [
    aws_s3_bucket.landing.arn,
    aws_sqs_queue.events.arn,
    aws_dynamodb_table.checkpoints.arn,
  ]
}

resource "aws_iam_openid_connect_provider" "github" {
  url            = "https://token.actions.githubusercontent.com"
  client_id_list = ["sts.amazonaws.com"]
}

data "aws_iam_policy_document" "plan_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:${var.github_repository}:pull_request"]
    }
  }
}

data "aws_iam_policy_document" "apply_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:${var.github_repository}:ref:${var.github_apply_ref}"]
    }
  }
}

# Plan role: read-only on the managed resources, read on state, and write on
# the lock object only (use_lockfile makes plan create and delete it).
data "aws_iam_policy_document" "plan" {
  statement {
    sid       = "StateRead"
    actions   = ["s3:GetObject"]
    resources = [local.state_key_arn]
  }

  statement {
    sid       = "StateList"
    actions   = ["s3:ListBucket"]
    resources = [local.state_bucket_arn]
  }

  statement {
    sid       = "StateLock"
    actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
    resources = [local.state_lock_arn]
  }

  statement {
    sid = "ReadLanding"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketAcl",
      "s3:GetBucketCORS",
      "s3:GetBucketLocation",
      "s3:GetBucketLogging",
      "s3:GetBucketObjectLockConfiguration",
      "s3:GetBucketOwnershipControls",
      "s3:GetBucketPolicy",
      "s3:GetBucketPublicAccessBlock",
      "s3:GetBucketRequestPayment",
      "s3:GetBucketTagging",
      "s3:GetBucketVersioning",
      "s3:GetBucketWebsite",
      "s3:GetAccelerateConfiguration",
      "s3:GetEncryptionConfiguration",
      "s3:GetLifecycleConfiguration",
      "s3:GetReplicationConfiguration",
    ]
    resources = [aws_s3_bucket.landing.arn]
  }

  statement {
    sid = "ReadQueue"
    actions = [
      "sqs:GetQueueAttributes",
      "sqs:ListQueueTags",
    ]
    resources = [aws_sqs_queue.events.arn]
  }

  statement {
    sid = "ReadTable"
    actions = [
      "dynamodb:DescribeTable",
      "dynamodb:DescribeContinuousBackups",
      "dynamodb:DescribeTimeToLive",
      "dynamodb:ListTagsOfResource",
    ]
    resources = [aws_dynamodb_table.checkpoints.arn]
  }
}

# Apply role: create/update/delete on the three managed resources and state
# read/write. It cannot change IAM, so it cannot widen its own access.
data "aws_iam_policy_document" "apply" {
  source_policy_documents = [data.aws_iam_policy_document.plan.json]

  statement {
    sid       = "StateWrite"
    actions   = ["s3:PutObject", "s3:DeleteObject"]
    resources = [local.state_key_arn]
  }

  statement {
    sid = "ManageLanding"
    actions = [
      "s3:CreateBucket",
      "s3:DeleteBucket",
      "s3:PutBucketAcl",
      "s3:PutBucketCORS",
      "s3:PutBucketLogging",
      "s3:PutBucketOwnershipControls",
      "s3:PutBucketPolicy",
      "s3:DeleteBucketPolicy",
      "s3:PutBucketPublicAccessBlock",
      "s3:PutBucketRequestPayment",
      "s3:PutBucketTagging",
      "s3:PutBucketVersioning",
      "s3:PutAccelerateConfiguration",
      "s3:PutEncryptionConfiguration",
      "s3:PutLifecycleConfiguration",
    ]
    resources = [aws_s3_bucket.landing.arn]
  }

  statement {
    sid = "ManageQueue"
    actions = [
      "sqs:CreateQueue",
      "sqs:DeleteQueue",
      "sqs:SetQueueAttributes",
      "sqs:TagQueue",
      "sqs:UntagQueue",
    ]
    resources = [aws_sqs_queue.events.arn]
  }

  statement {
    sid = "ManageTable"
    actions = [
      "dynamodb:CreateTable",
      "dynamodb:DeleteTable",
      "dynamodb:UpdateTable",
      "dynamodb:UpdateContinuousBackups",
      "dynamodb:UpdateTimeToLive",
      "dynamodb:TagResource",
      "dynamodb:UntagResource",
    ]
    resources = [aws_dynamodb_table.checkpoints.arn]
  }
}

resource "aws_iam_role" "ci_plan" {
  name                 = "ingest-ci-plan"
  description          = "Assumed by platform/ingest pull-request workflows to run terraform plan with read-only access."
  assume_role_policy   = data.aws_iam_policy_document.plan_trust.json
  max_session_duration = 3600
}

resource "aws_iam_role_policy" "ci_plan" {
  name   = "terraform-plan"
  role   = aws_iam_role.ci_plan.id
  policy = data.aws_iam_policy_document.plan.json
}

resource "aws_iam_role" "ci_apply" {
  name                 = "ingest-ci-apply"
  description          = "Assumed by platform/ingest workflows on the main branch to run terraform apply."
  assume_role_policy   = data.aws_iam_policy_document.apply_trust.json
  max_session_duration = 3600
}

resource "aws_iam_role_policy" "ci_apply" {
  name   = "terraform-apply"
  role   = aws_iam_role.ci_apply.id
  policy = data.aws_iam_policy_document.apply.json
}

output "ci_plan_role_arn" {
  description = "ARN of the role the pull-request plan job assumes through GitHub OIDC."
  value       = aws_iam_role.ci_plan.arn
}

output "ci_apply_role_arn" {
  description = "ARN of the role the main-branch apply job assumes through GitHub OIDC."
  value       = aws_iam_role.ci_apply.arn
}
EOF
sed -i '/^data "aws_caller_identity"/,+1d' ci_access.tf
terraform fmt -check -diff; which tflint trivy tfsec checkov; ls -a | head -20

